--- rtl/fp_pkg.sv	
+++ rtl/fp_pkg.sv	
@@ -1,37 +1,38 @@
 // IEEE 754-2019 floating-point helper definitions.
 //
 // Types and constants shared by the datapath modules. The bit positions of
 // the exception flags and the enum values must stay in sync with
 // tests/reference/formats.py (bit-exact oracle).

 package fp_pkg;

   // Rounding-direction attributes (clause 4.3).
   typedef enum logic [2:0] {
     RM_RNE = 3'd0,  // roundTiesToEven (4.3.1)
     RM_RNA = 3'd1,  // roundTiesToAway (4.3.1)
     RM_RZ  = 3'd2,  // roundTowardZero (4.3.2)
     RM_RP  = 3'd3,  // roundTowardPositive (4.3.2)
     RM_RM  = 3'd4   // roundTowardNegative (4.3.2)
   } rounding_t;

   // Operations (clause 5.4.1).
   typedef enum logic [2:0] {
     OP_ADD = 3'd0,  // addition
     OP_SUB = 3'd1,  // subtraction
-    OP_MUL = 3'd2   // multiplication
+    OP_MUL = 3'd2,  // multiplication
+    OP_DIV = 3'd3   // division
   } op_t;

   // Exception flags (clause 7), bit positions of the 5-bit flags output.
   // These are the package's public flag API (mirrored in
   // tests/reference/formats.py). Each op uses a subset, so Verilator flags
   // unused constants per instance; that is expected and not a defect.
   /* verilator lint_off UNUSEDPARAM */
   localparam int FLAG_INVALID   = 4;  // 7.2
   localparam int FLAG_DIV0      = 3;  // 7.3
   localparam int FLAG_OVERFLOW  = 2;  // 7.4
   localparam int FLAG_UNDERFLOW = 1;  // 7.5
   localparam int FLAG_INEXACT   = 0;  // 7.6
   /* verilator lint_on UNUSEDPARAM */

 endpackage

Index: rtl/fp_unit.sv
===================================================================
--- rtl/fp_unit.sv	
+++ rtl/fp_unit.sv	
@@ -1,64 +1,78 @@
 // IEEE 754-2019 floating-point unit top level.
 //
 // Combinational, parameterized by the format: W_EXP exponent bits and W_MANT
 // fraction bits (3.3, 3.7 "extendable precision"). Decodes the operation
 // select and drives the per-operation datapaths (added incrementally per the
 // project plan; add/sub first, then mul, div, sqrt, fma, min/max, ...).
-// OP_MUL selects the multiply datapaths (fp_mul/fp_mul_e8m0); OP_ADD/OP_SUB
-// select the add datapaths (fp_add/fp_add_e8m0).
+// OP_MUL selects the multiply datapaths (fp_mul/fp_mul_e8m0), OP_DIV the
+// divide datapaths (fp_div/fp_div_e8m0); OP_ADD/OP_SUB select the add
+// datapaths (fp_add/fp_add_e8m0).
 //
 // W_MANT = 0 selects the dedicated E8M0 (1 + W_EXP + 0 bits, microscaling
 // shared-exponent format): the generic datapaths cannot be elaborated at that
 // width by Verilator 5.020, and the p = 1 tie rules are implemented
 // explicitly in the *_e8m0 modules.

 module fp_unit #(
   parameter int W_EXP  = 8,
   parameter int W_MANT = 23
 ) (
   input  fp_pkg::op_t        mode,
   input  fp_pkg::rounding_t  rm,
   input  logic [1+W_EXP+W_MANT-1:0] a,
   input  logic [1+W_EXP+W_MANT-1:0] b,
   output logic [1+W_EXP+W_MANT-1:0] y,
   output logic [4:0]               flags
 );

   logic [1+W_EXP+W_MANT-1:0] y_add;
   logic [4:0]                flags_add;
   logic [1+W_EXP+W_MANT-1:0] y_mul;
   logic [4:0]                flags_mul;
+  logic [1+W_EXP+W_MANT-1:0] y_div;
+  logic [4:0]                flags_div;

   generate
     if (W_MANT > 0) begin : g_generic
       fp_add #(.W_EXP(W_EXP), .W_MANT(W_MANT)) u_fp_add (
         .a(a), .b(b), .rm(rm), .op(mode),
         .y(y_add), .flags(flags_add)
       );
       fp_mul #(.W_EXP(W_EXP), .W_MANT(W_MANT)) u_fp_mul (
         .a(a), .b(b), .rm(rm),
         .y(y_mul), .flags(flags_mul)
       );
+      fp_div #(.W_EXP(W_EXP), .W_MANT(W_MANT)) u_fp_div (
+        .a(a), .b(b), .rm(rm),
+        .y(y_div), .flags(flags_div)
+      );
     end else begin : g_e8m0
       fp_add_e8m0 #(.W_EXP(W_EXP)) u_fp_add (
         .a(a), .b(b), .rm(rm), .op(mode),
         .y(y_add), .flags(flags_add)
       );
       fp_mul_e8m0 #(.W_EXP(W_EXP)) u_fp_mul (
         .a(a), .b(b), .rm(rm),
         .y(y_mul), .flags(flags_mul)
       );
+      fp_div_e8m0 #(.W_EXP(W_EXP)) u_fp_div (
+        .a(a), .b(b), .rm(rm),
+        .y(y_div), .flags(flags_div)
+      );
     end
   endgenerate

   always_comb begin
     if (mode == fp_pkg::OP_MUL) begin
       y     = y_mul;
       flags = flags_mul;
+    end else if (mode == fp_pkg::OP_DIV) begin
+      y     = y_div;
+      flags = flags_div;
     end else begin
