     if (mode == fp_pkg::OP_MUL) begin
       y     = y_mul;
       flags = flags_mul;
     end else if (mode == fp_pkg::OP_DIV) begin
       y     = y_div;
       flags = flags_div;
+    end else if (mode == fp_pkg::OP_SQRT) begin
