    if (shift_p >= 0) begin
      placed_p = (ACC_W)'(P) << shift_p;
      sticky_p = 1'b0;
    end else begin
      placed_p = (ACC_W)'(P >> (-shift_p));
      sticky_p = |P[-shift_p-1:0];
    end
