      rsign = prod_sign;
      cancel = 1'b0;
      diff_sticky = 1'b0;
    end else if (placed_p >= placed_c) begin
      acc = {1'b0, placed_p} - {1'b0, placed_c};
      rsign = prod_sign;
      cancel = (acc == '0);
      diff_sticky = sticky_p | sticky_c;
      if (diff_sticky) acc = acc - 1;
    end else begin
      acc = {1'b0, placed_c} - {1'b0, placed_p};
      rsign = c_sign;
      cancel = (acc == '0);
      diff_sticky = sticky_p | sticky_c;
      if (diff_sticky) acc = acc - 1;
