      e_res = (W_EXP+4)'(top) + (W_EXP+4)'($signed(p0) - PTOP);
    end else if (p0 < TARGET) begin
      norm = acc << (TARGET - p0);
      e_res = (W_EXP+4)'(top) + (W_EXP+4)'($signed(p0) - PTOP);
    end else begin
      norm = acc;
      e_res = (W_EXP+4)'(top) + (W_EXP+4)'($signed(p0) - PTOP);
